<template><article class="learning-task-card" :class="{ 'learning-task-card--done':task.done }"><div class="task-card-head"><span class="m-badge" :class="task.done?'m-badge--success':'m-badge--info'">{{ task.done?'已完成（手动确认）':task.localState==='deferred'?'已延期（本机）':task.localState==='active'?'进行中':'待开始' }}</span><span>{{ task.minutes }} 分钟建议</span></div><h3>{{ task.title }}</h3><p>{{ goalName || '独立学习任务' }} · {{ task.type }}</p><dl><dt>完成条件</dt><dd>{{ task.condition }}</dd></dl><div class="workspace-actions"><button v-if="!task.done" class="m-btn m-btn--primary m-btn--sm" :disabled="busy" @click="emit('start')">{{ task.localState==='active'?'继续学习':'开始这一项' }}<MobileIcon name="chevronRight" :size="15"/></button><button class="m-btn m-btn--ghost m-btn--sm" :disabled="busy" @click="emit('complete')">{{ task.done?'撤销完成标记':'确认已完成' }}</button><button v-if="!task.done" class="workspace-text-action" @click="emit('defer')">{{ task.localState==='deferred'?'恢复到待开始':'稍后再做' }}</button></div></article></template>
<script setup lang="ts">
import MobileIcon from './MobileIcon.vue'
defineProps<{task:{title:string;done:boolean;minutes:number;condition:string;type:string;localState:string};goalName?:string;busy?:boolean}>();const emit=defineEmits<{start:[];complete:[];defer:[]}>()
</script>
